import { NQ } from '../shared/classNames.js';
import { renderVariableRule, tabsVariables } from '../shared/variables.js';

/*
  generateTabsCSS(config, theme) -> Tabs.css source string.

  Mirrors the library's token contract: import the structural stylesheet, then
  override only --nq-tabs-* variables.
*/

export function generateTabsCSS(config, theme = {}) {
  return [
    '/* Tabs.css — generated by Nasaq UI. Pairs with Tabs.jsx.',
    '   Structural rules come from nasaq/styles.css. */',
    '',
    "@import 'nasaq/styles.css';",
    '',
    '@layer nasaq {',
    renderVariableRule(`.${NQ.tabs}`, tabsVariables(config, theme)),
    '}',
  ].join('\n');
}
